// ─── Main ─────────────────────────────────────────────────────────────────────
function run() {
  // 1. Inject EN
  const enPath = path.join(LOCALES_DIR, 'en', 'translation.json');
  const enData = JSON.parse(fs.readFileSync(enPath, 'utf8'));
  enData.home = HOME_EN;
  fs.writeFileSync(enPath, JSON.stringify(enData, null, 2), 'utf8');
  console.log('✅ en/translation.json — home keys injected');

  // 2. Inject fully-translated langs
  for (const [lang, homeKeys] of Object.entries(TRANSLATIONS)) {
    const filePath = path.join(LOCALES_DIR, lang, 'translation.json');
    if (!fs.existsSync(filePath)) { console.warn(`⚠️  ${lang} not found, skip`); continue; }
    const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    data.home = homeKeys;
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
    console.log(`✅ ${lang}/translation.json — home keys injected`);
  }

  // 3. Inject simple langs (EN content as placeholder, i18next fallback handles display)
  for (const lang of SIMPLE_LANGS) {
    const filePath = path.join(LOCALES_DIR, lang, 'translation.json');
    if (!fs.existsSync(filePath)) { console.warn(`⚠️  ${lang} not found, skip`); continue; }
    const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    data.home = SIMPLE_HOME(lang);
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
    console.log(`✅ ${lang}/translation.json — home keys (EN fallback) injected`);
  }

  console.log('\n🎉 Done! home.* keys injected into all 30 locale files.');
}

run();
